import os
from dataclasses import dataclass
from typing import Optional

import boto3


AWS_REGION_ENV = "AWS_REGION"
AWS_DEFAULT_REGION_ENV = "AWS_DEFAULT_REGION"
AWS_KMS_KEY_ID_ENV = "AWS_KMS_KEY_ID"
AWS_KMS_ENDPOINT_URL_ENV = "AWS_KMS_ENDPOINT_URL"


@dataclass(frozen=True)
class SecurityConfig:
    region_name: Optional[str]
    key_id: Optional[str]
    endpoint_url: Optional[str]


def load_security_config() -> SecurityConfig:
    region_name = os.environ.get(AWS_REGION_ENV) or os.environ.get(AWS_DEFAULT_REGION_ENV)
    key_id = os.environ.get(AWS_KMS_KEY_ID_ENV)
    endpoint_url = os.environ.get(AWS_KMS_ENDPOINT_URL_ENV)
    return SecurityConfig(region_name=region_name, key_id=key_id, endpoint_url=endpoint_url)


def get_kms_client(region_name: Optional[str] = None, endpoint_url: Optional[str] = None):
    config = load_security_config()
    session = boto3.session.Session(region_name=region_name or config.region_name)
    return session.client("kms", endpoint_url=endpoint_url or config.endpoint_url)


def resolve_key_id(key_id: Optional[str] = None) -> Optional[str]:
    return key_id or load_security_config().key_id


def security_headers() -> dict[str, str]:
    config = load_security_config()
    headers = {"x-security-provider": "aws_kms"}
    if config.region_name:
        headers["x-aws-region"] = config.region_name
    if config.key_id:
        headers["x-kms-key-id"] = config.key_id
    return headers

from dataclasses import dataclass, field
from typing import Any, Mapping, Optional
import base64


def _b64decode(value: str) -> bytes:
    return base64.b64decode(value.encode("utf-8"))


def _b64encode(value: bytes) -> str:
    return base64.b64encode(value).decode("utf-8")


def normalize_text(value: Optional[Any]) -> Optional[str]:
    if value is None:
        return None
    text = str(value).strip()
    return text or None


def normalize_key_id(value: Optional[Any]) -> Optional[str]:
    text = normalize_text(value)
    if text is None:
        return None
    return text


def normalize_bytes(value: Optional[Any]) -> Optional[bytes]:
    if value is None:
        return None
    if isinstance(value, bytes):
        return value
    if isinstance(value, bytearray):
        return bytes(value)
    if isinstance(value, str):
        text = value.strip()
        if not text:
            return None
        try:
            return _b64decode(text)
        except Exception:
            return text.encode("utf-8")
    return str(value).encode("utf-8")


def normalize_bytes_b64(value: Optional[Any]) -> Optional[str]:
    data = normalize_bytes(value)
    if data is None:
        return None
    return _b64encode(data)


def normalize_bool(value: Optional[Any]) -> Optional[bool]:
    if value is None or isinstance(value, bool):
        return value
    if isinstance(value, str):
        lowered = value.strip().lower()
        if lowered in {"1", "true", "yes", "y", "on"}:
            return True
        if lowered in {"0", "false", "no", "n", "off"}:
            return False
    return bool(value)


@dataclass(frozen=True)
class KeyReference:
    key_id: Optional[str] = None
    key_arn: Optional[str] = None
    alias_name: Optional[str] = None

    @classmethod
    def from_mapping(cls, mapping: Mapping[str, Any]) -> "KeyReference":
        return cls(
            key_id=normalize_key_id(mapping.get("key_id") or mapping.get("KeyId")),
            key_arn=normalize_text(mapping.get("key_arn") or mapping.get("KeyArn")),
            alias_name=normalize_text(mapping.get("alias_name") or mapping.get("AliasName")),
        )


